{"file_path":"/work/tests/test_spec.py","content":""""Regression tests for the behavior specified in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("b", 1, None)]) == 0.0


def test_conversion_rate_empty():
    rate = conversion_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 1, False), session("c", 1, None), session("d", 1, False)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_pooled_rate_without_sessions(groups):
    rate = pooled_conversion_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_flags_and_field_whitespace():
    result = parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"])
    assert result == [session("a", 1, True), session("b", -2, False), session("c", 3, None)]
    assert result[0]["converted"] is True
    assert result[1]["converted"] is False
    assert result[2]["converted"] is None


def test_parse_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# not,a,valid,record", "a,1,1", "b#tag,2,0"]
    assert parse_session_log(iter(lines)) == [session("a", 1, True), session("b#tag", 2, False)]
    assert parse_session_log(["", " # comment"]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1.5,0", "a,,1"])
def test_parse_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", " \t", "ok,1,0", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts():
    events = [
        session("a", 9, True),
        session("b", 2, True),
        session("c", 1, True),
        session("a", 2, None),
        session("b", 2, False),
    ]
    original = [dict(event) for event in events]
    assert dedupe_sessions(events) == [events[2], events[3], events[4]]
    assert events == original
    assert dedupe_sessions([]) == []


def test_daily_counts_fill_gaps_include_endpoints_and_ignore_outside_range():
    events = [
        session("before", 0, True), session("a", 1, True),
        session("b", 1, True), session("c", 2, False),
        session("d", 2, None), session("e", 4, True),
        session("after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_campaign_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 5, None)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_without_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [session("z", 1, True)],
        "empty": [],
        "low": [session("l", 1, False)],
        "a": [session("a", 1, True)],
        "middle": [session("m", 1, True), session("n", 1, None)],
    }
    assert top_converting_groups(groups, 3) == ["a", "z", "middle"]
    assert top_converting_groups(groups, 10) == ["a", "z", "middle", "low"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({}, 3) == []
    assert top_converting_groups({"empty": []}, 3) == []


def test_rate_by_group_sorts_keys_and_preserves_empty_as_none():
    groups = {
        "z": [session("z", 1, False)],
        "m": [session("m", 1, True), session("n", 1, None)],
        "a": [],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": None, "m": 0.5, "z": 0.0}
    assert list(result) == ["a", "m", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5], 3),
     ([1, -1, 1], 1), ([1, 2, 3], 3), ([1, 2, 0, 1, 0], 2)],
)
def test_longest_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_conversion_streak(counts) == expected
